VALUES ('App\\Models\\ManadoTour', '40', 'ko', '마나도 투아 섬 트레킹 & 부나켄', '<ul><li data-list-item-id="e00fb6c1118e49e21a7f97503eaf992e5"><p style="text-align:justify;">전용 육상 차량&nbsp;</p></li><li data-list-item-id="e6716471c34f5fc9b3179bcb936fa58c3"><p style="text-align:justify;">마나도 투아 섬 - 부나켄 섬 보트</p></li><li data-list-item-id="e7dbd5d5b9349e351d2566cfe3d45e1f5"><p style="text-align:justify;">숙련된 투어 가이드&nbsp;</p></li><li data-list-item-id="ee7e0b2f9144abb63771706ac469d1409"><p style="text-align:justify;">기사 &amp; 선원&nbsp;</p></li><li data-list-item-id="e5f742e4e693df53a07f0d451ed536d14"><p style="text-align:justify;">관광지 입장료</p></li><li data-list-item-id="e16a242b2af99118485dc893e4c9eb32e"><p style="text-align:justify;">주차료, 도시락&nbsp;</p></li><li data-list-item-id="e4ee5b7dc98d3b764f8675efcd7904bc8"><p style="text-align:justify;">1인당 생수 1병&nbsp;</p></li><li data-list-item-id="e19afe33283d9f5a1420ae129e922a3cd"><p style="text-align:justify;">일정표에 따른 투어 서비스</p></li></ul>', '<ul><li data-list-item-id="e369b588efdeecf96f0f185253b99bd9d">항공권&nbsp;</li><li data-list-item-id="ee1063332712c6f3757ec551ca5a90c42">공항세</li><li data-list-item-id="e76eb00c159fe609d319cbf81974ed8fd">포터 서비스</li><li data-list-item-id="e1cc4535135e2d767b6fafc8aa29d78af">호텔 숙박&nbsp;</li><li data-list-item-id="eaf01991d1adab37bf2ca6f7fd2e7f0bf">가이드 &amp; 기사 팁</li><li data-list-item-id="e1cadc73e8b1505883ffb1bf721a2db91">선택 관광 &amp; 일정에 명시되지 않은 기타 개인 경비</li></ul>', NOW(), NOW())
