VALUES ('App\\Models\\ManadoTour', '41', 'ko', '와루가 유적 & 바투 앙우스 해안 투어', '<ul><li data-list-item-id="ee44c315611f4315dc32a35e8ba7a8932"><p style="text-align:justify;">차량&nbsp;</p></li><li data-list-item-id="e9aebf7e500b9218ae96e4a9735b5887c"><p style="text-align:justify;">보트 &amp; 스노클링 장비</p></li><li data-list-item-id="ea78c4cba10fab0194db11ca30051e78c"><p style="text-align:justify;">숙련된 투어 가이드, 기사 &amp; 선원</p></li><li data-list-item-id="e763a6a58cf17409d04eff769ee730b2b"><p style="text-align:justify;">관광지 입장료 &amp; 주차료</p></li><li data-list-item-id="ea46383f45241738ea5e48e7cbee46faa"><p style="text-align:justify;">중식 &amp; 1인당 생수 1병</p></li><li data-list-item-id="e867486aa2ffffd707bde11fb9e6db2af"><p style="text-align:justify;">일정표에 따른 투어 서비스</p></li></ul>', '<ul><li data-list-item-id="e369b588efdeecf96f0f185253b99bd9d">항공권&nbsp;</li><li data-list-item-id="ee1063332712c6f3757ec551ca5a90c42">공항세</li><li data-list-item-id="e76eb00c159fe609d319cbf81974ed8fd">포터 서비스</li><li data-list-item-id="e1cc4535135e2d767b6fafc8aa29d78af">호텔 숙박&nbsp;</li><li data-list-item-id="eaf01991d1adab37bf2ca6f7fd2e7f0bf">가이드 &amp; 기사 팁</li><li data-list-item-id="e1cadc73e8b1505883ffb1bf721a2db91">선택 관광 &amp; 일정에 명시되지 않은 기타 개인 경비</li></ul>', NOW(), NOW())
