-- paket 21 hari 1 (itinerary 2749)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('2749', 'ko', '일정', '<p style="text-align:justify;">오전 8시 <strong>메가마스 부두</strong>에서 투어 가이드와 미팅 후 <strong>부나켄 섬</strong> 일일 투어를 시작합니다. 메가마스 부두에서 보트로 약 30분간 이동해 <strong>부나켄 섬</strong>에 도착합니다. 현재 부나켄은 새롭게 정비되어 한층 세련된 <strong>부나켄 관광 부두(뉴 부나켄)</strong>를 갖추고 있어, 섬의 절경을 배경으로 멋진 사진과 영상을 남기실 수 있습니다.&nbsp;</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">화려한 산호초와 형형색색의 열대어가 서식하는 부나켄 해양공원의 수중 절경을 <i>선택 </i>스노클링 또는 다이빙으로 만나 보세요. 자유 시간에는 섬의 고요한 해변 분위기를 즐기실 수도 있습니다. 중식은 해변가 현지 레스토랑에서 제공됩니다.&nbsp;</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">식사 후에는 자유 시간을 더 즐기시거나 스노클링&middot;다이빙을 이어가실 수 있습니다(선택 사항). 오후에는 마나도 메가마스 부두로 돌아옵니다. 투어 종료.</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 19 hari 1 (itinerary 2751)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('2751', 'ko', '일정', '<p style="text-align:justify;">참가자는 오전에 미팅 포인트에서 픽업되어 손데르 <strong>팀부카르 마을</strong>의 <strong>래프팅 장소</strong>로 이동합니다. 래프팅을 시작하기 전, 고무보트 위에서 균형을 유지하기 위한 기본 동작과 안전 수칙을 포함한 짧은 교육이 진행됩니다.&nbsp;</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">래프팅 중에는 국제 표준 안전 장비를 갖춘 숙련된 래프팅 가이드 두 명이 동행합니다. 니망가 강의 짜릿한 급류를 헤쳐 나가는 약 90분 동안, 주변의 빼어난 자연 경관도 함께 즐기실 수 있습니다.&nbsp;</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">이후 마나도 시내로 돌아와 미팅 포인트에서 하차합니다. 투어가 종료됩니다.</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 17 hari 1 (itinerary 2753)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('2753', 'ko', '일정', '<p style="text-align:justify;"><strong>로콘산</strong>은 토모혼에서 가장 큰 산 중 하나이며, 해발 1,580미터의 활화산입니다. 이름 그대로 &ldquo;로콘&rdquo;은 가장 오래되고 가장 위대하다는 뜻입니다. <strong>톰팔루안 분화구</strong>로 알려진 활동 중인 분화구는 산자락에 자리하고 있습니다.&nbsp;</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">픽업 장소에서 토모혼 또는 로콘산 기슭까지 차량으로 약 1시간 30분 이동한 뒤, 약 2시간 도보로 올라 분화구 가장자리에 도착합니다. 현재 트레킹은 분화구까지만 진행되며, 분화구는 정상까지의 대략 중간 지점에 있습니다.&nbsp;</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">로콘산은 빼어난 자연 경관과 함께 등반의 짜릿한 도전을 선사합니다. 등산로를 따라 토모혼 시내의 아름다운 전경을 비롯한 멋진 풍경을 감상하실 수 있습니다.&nbsp;</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">트레킹을 마친 뒤 현지 레스토랑에서 중식을 드십니다. 식사 후 마나도 시내로 돌아와 지정된 장소에서 하차합니다. 투어 종료.</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 15 hari 1 (itinerary 2755)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('2755', 'ko', '일정', '<p style="text-align:justify;">참가자는 오전에 픽업되어 랍랍 해변으로 향합니다. 도착 후에는 아름다운 랍랍 해변에서 특별한 체험이 시작됩니다. 먼저 울창한 맹그로브 숲을 감싸는 잔잔한 물길을 카누로 통과하며, 몇 분 지나지 않아 맹그로브 나무 사이에서 자주 발견되는 작고 신비로운 영장류 <strong>안경원숭이</strong>를 찾아 나섭니다.&nbsp;</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">고요한 자연과 숲의 소리가 여정을 함께하며, 북술라웨시의 아름다운 자연 속에서 잊지 못할 순간을 만들어 줍니다. <strong>안경원숭이</strong>를 발견하면 자유롭게 사진을 찍으며 그 순간을 담으실 수 있습니다.&nbsp;</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">이후 랍랍 해안으로 돌아온 뒤 툼파산 고지대로 이동하여, 산기슭에서 아름다운 <strong>일몰</strong>을 감상하며 <strong>다양한 마나도 전통 간식</strong>을 즐기실 수 있습니다. 피상 고렝 삼발 로아, 바타타 고렝 굴라 메라, 에스 카짱 브레네본 등이 준비됩니다 <i>(선택 사항, 개인 부담)</i>. 이후 미팅 포인트로 이동하며 투어가 종료됩니다.</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 14 hari 1 (itinerary 2756)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('2756', 'ko', '일정', '<p style="text-align:justify;">오전 10시 툼파산에서 미팅 및 인사.</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;"><strong>툼파산 </strong>패러글라이딩은 모험을 즐기는 분과 자연을 사랑하는 분 모두에게 잊지 못할 경험입니다. 약 1,000미터 상공을 날며 새처럼 자유롭게 비행하는 짜릿한 감각과 함께, 산악 경관과 울창한 녹음, 그리고 눈 아래 펼쳐지는 맑고 푸른 바다를 감상하실 수 있습니다.&nbsp;</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">툼파산 패러글라이딩 장소는 기상이 안정적이고 바람이 잔잔해 초보자는 물론 실력을 다지려는 분에게도 안전하고 이상적인 곳입니다. 전문 패러글라이딩 강사가 동행하며 적절한 안전 장비가 제공됩니다.&nbsp;</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">툼파산 패러글라이딩은 짜릿하면서도 아름다운 경험으로, 마나도 여행을 오래도록 기억에 남게 만들어 줍니다.</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 27 hari 1 (itinerary 4915)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('4915', 'ko', '일정', '<p style="text-align:justify;">마나도 호텔에서 조식 후, 북술라웨시에서 가장 활발한 화산 중 하나이며 웅장한 화산 경관과 숨 막히는 자연 풍경으로 이름난 <strong>소푸탄산</strong>으로 출발합니다.</p><p style="text-align:justify;">🕐 <strong>마나도에서 소푸탄산 기슭까지 이동 시간:</strong> 교통 및 기상 상황에 따라 <strong>차량으로 약 2.5~3시간</strong>.</p><p style="text-align:justify;">이동 중에는 시골 풍경과 코코넛 농원, 북술라웨시의 아름다운 산악 경관이 이어져 이동 자체가 여정의 일부가 됩니다.</p><p style="text-align:justify;">트레킹 시작 지점에 도착하면 <strong>소푸탄산</strong> 등반을 준비합니다. 등산로는 울창한 숲길과 탁 트인 사바나, 화산암 지형, 그리고 과거 화산 활동이 빚어낸 장관이 어우러진 독특한 구성입니다.</p><p style="text-align:justify;">🕐 <strong>예상 트레킹 소요 시간(왕복):</strong> 기상 상황과 체력, 보행 속도에 따라 <strong>약 4~5시간</strong>.</p><p style="text-align:justify;">📸 길을 따라 펼쳐지는 웅장한 파노라마와 화산 지형을 감상하세요. 자연 애호가와 사진가, 모험을 찾는 분 모두에게 보람 있는 경험입니다.</p><p style="text-align:justify;">트레킹을 마친 뒤 차량으로 돌아와 마나도 호텔로 이동해 충분한 휴식을 취하십시오.</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 26 hari 1 (itinerary 5010)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('5010', 'ko', '일정', '<p style="text-align:justify;">오전 8시 <strong>메가마스 부두</strong>에서 투어 가이드와 미팅 후 <strong>아일랜드 호핑 </strong>일일 투어를 시작합니다. 메가마스 부두에서 보트로 약 30분간 이동해 <strong>부나켄 섬</strong>에 도착합니다.&nbsp;</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">도착 후에는 <strong>부나켄 해양공원</strong>을 방문합니다. <strong>부나켄 섬</strong> 일대를 감싸는 빼어난 산호초와 수천 종의 형형색색 물고기로 유명한 곳입니다. 현재 <strong>부나켄 섬</strong>은 <strong>부나켄 관광 부두</strong>를 비롯해 한층 매력적으로 정비되어, 가족&middot;친구와 함께 사진을 남기기에 좋습니다.&nbsp;</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">이후 스노클링이나 다이빙을 선택하실 수 있으며, 물속에서 직접 손으로 물고기에게 먹이를 주며 수영하실 수도 있습니다. 중식은 <strong>부나켄 섬</strong>의 현지 레스토랑에서 제공됩니다.&nbsp;</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">식사 후에는 <strong>실라덴 섬</strong>과 <strong>나인 모래톱</strong>으로 향합니다. 각 섬에서 사진과 영상을 남기고, 산책을 즐기며 <strong>실라덴 섬</strong>과 <strong>나인 모래톱</strong>의 자연을 만끽하실 수 있습니다.&nbsp;</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">오후에는 마나도 메가마스 부두로 돌아옵니다. 투어 종료.</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 22 hari 1 (itinerary 5018)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('5018', 'ko', '일정', '<p style="text-align:justify;">참가자는 픽업 장소에서 투어 가이드를 만나 곧바로 시티 투어를 시작합니다. 마나도 시내 중심가와 차이나타운, 그리고 <strong>반 힌 키옹 사원</strong>(18세기에 세워진 마나도에서 가장 오래된 사원, 약 300년 역사)을 둘러봅니다.&nbsp;</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">이어 <strong>센트룸 교회</strong>(네덜란드 식민지 시대에 세워진 북술라웨시 최초의 개신교 교회)와 제2차 세계대전 기념비(1942년 일본군에 의한 마나도 파괴를 기리는 기념비)를 지납니다. 중식은 마나도 전통 방식으로 조리한 <strong>참치 요리가 특별한 현지 레스토랑</strong>에서 제공됩니다.&nbsp;</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">이후 링로드 치트라 랜드 지역으로 이동해 <strong>예수 축복상</strong>을 가까이에서 감상합니다. 마나도 시내를 향해 공중에 떠 있는 듯한 자세로 세워진 예수상입니다. 이어서 <strong>마카테테 언덕</strong>으로 향합니다. 해발 200미터 언덕 위에서 마나도 시내와 마나도 섬, 부나켄 섬, 실라덴 섬, 드넓은 바다, 그리고 북술라웨시 최고봉인 클라밧산까지 조망하실 수 있습니다.&nbsp;</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">석식은 선택 사항입니다. 식사 후 픽업 장소로 돌아오며 투어가 마무리됩니다.</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 20 hari 1 (itinerary 5019)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('5019', 'ko', '일정', '<p style="text-align:justify;">참가자는 오전에 투어 가이드의 픽업으로 <strong>미나하사 고원</strong>으로 향하며, 해발 500미터에서 마나도 시내를 조망할 수 있는 <strong>티노르</strong> 지역을 지납니다. 토모혼에 도착하면 <strong>펠랑기 관광공원</strong>을 방문해 형형색색의 꽃들이 빚어내는 아름다움을 감상합니다.&nbsp;</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">다음 목적지는 <strong>토모혼 익스트림 시장</strong>으로, <i><strong>파니키(박쥐), 숲쥐, 뱀 등 다양한 야생동물</strong></i> 고기를 가까이에서 보실 수 있습니다. 다른 장소에서는 <strong>쿠쭈르, 아팡 굴라 메라, 도돌</strong> 등 마나도 전통 과자를 <strong>즉석에서 만드는</strong> 과정도 지켜보실 수 있습니다.&nbsp;</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">이어서 인스타그램에 어울리는 포토 스폿이 있는 <strong>투우르 마세링</strong>의 <strong>아렌 야자 숲</strong>으로 향합니다. 사진 명소뿐 아니라, 아렌 나무 수액을 발효&middot;증류해 만드는 <i><strong>현지 전통주 </strong></i><strong>&lsquo;짭 티쿠스&rsquo;</strong>의 제조 과정도 함께 살펴보실 수 있습니다.&nbsp;</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">중식은 <strong>톤다노 호수</strong> 인근 현지 레스토랑에서 제공됩니다. 식사 후에는 <strong>부킷 카시</strong>로 이동합니다. 활동 중인 유황 분화구와 언덕 정상으로 이어지는 계단이 있는 독특한 자연 명소로, 빼어난 조망과 함께 색다른 문화 체험을 선사합니다. 이 지역에는 천연 유황 온천도 있어 수영을 하거나 족욕으로 피로를 푸실 수 있습니다(선택 사항).&nbsp;</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">여정은 <strong>리노우 호수</strong>로 이어집니다. 물빛이 시시각각 변하는 것으로 유명한 유황 호수로, 아름답고 고요한 풍경 속에서 커피 또는 차가 제공됩니다. 이후 마나도 시내로 돌아옵니다. 석식은 선택 사항입니다. 식사 후 지정된 하차 장소로 이동하며 투어가 종료됩니다.</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 39 hari 1 (itinerary 6223)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('6223', 'ko', '일정', '<p style="text-align:justify;">조식 후 저희 팀이 마나도 시내 호텔로 모시러 갑니다. 이후 북술라웨시 특유의 해안과 시골 풍경을 감상하며 세레이 리쿠팡 부두로 이동합니다. 부두에 도착하면 전용 보트를 타고 리쿠팡 일대에서 손꼽히는 스노클링 명소인 강가 섬 인근 해역으로 향합니다. 이곳에서는 원시 그대로의 산호초와 형형색색의 열대어, 시야가 탁월한 맑은 바다를 만나실 수 있습니다.</p><p style="text-align:justify;">스노클링을 마친 뒤에는 고운 백사장과 청록빛 바다로 유명한 리하가 섬으로 이동합니다. 수영을 즐기거나 해변에서 휴식을 취하고, 섬을 거닐거나 빼어난 열대 풍경을 배경으로 한 여러 포토 스폿에서 순간을 담아 보세요. 중식은 고요하고 자연스러운 분위기의 리하가 섬에서 제공됩니다.</p><p style="text-align:justify;">오후에는 보트로 세레이 리쿠팡 부두로 돌아온 뒤 육로로 마나도 시내로 향합니다. 호텔로 돌아가기 전, 마나도 기념품 센터에 들러 현지 특산 먹거리와 수공예품, 기념품을 둘러보실 수 있습니다. 이후 리쿠팡에서 가장 아름다운 두 열대 섬의 잊지 못할 경험을 안고 호텔로 모셔다 드립니다.</p><p style="text-align:justify;"><strong>투어 종료</strong></p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 24 hari 1 (itinerary 6888)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('6888', 'ko', '도착 – 투난 폭포 – 탕코코 자연보호구역', '<p style="text-align:justify;">오전 마나도 도착. 가이드와 만난 뒤 <strong>탈라완 마을</strong>에 있는 <strong>투난 폭포</strong>로 이동합니다. <strong>투난 폭포</strong>의 수원은 산 위의 강물로, 높이 약 86미터의 가파른 절벽을 따라 상당히 세차게 흘러내립니다. 손대지 않은 자연 그대로의 숲이 만들어 내는 분위기가 <strong>투난 폭포</strong> 자연 관광지의 아름다움을 한층 더해 줍니다.&nbsp;</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">이어서 <strong>탕코코 국립공원</strong>으로 곧장 이동합니다(오후에 도착하시는 경우 투난 폭포 일정을 생략하고 탕코코의 바투 푸티 마을로 바로 향합니다). 늦은 오후에는 숲에서 짧은 트레킹을 하며 이 공원의 주인공, 지구상에서 가장 작은 포유류인 안경원숭이를 찾아 나섭니다. 숙박은 탕코코 홈스테이에서 하십니다.</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 24 hari 2 (itinerary 6889)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('6889', 'ko', '탕코코 종일 투어', '<p style="text-align:justify;">홈스테이에서 조식을 마친 뒤, 탕코코 자연보호구역에서 북술라웨시의 고유종 탐방을 시작합니다. 검은짧은꼬리원숭이(북술라웨시 고유의 검은 원숭이), 안경원숭이(세계에서 가장 작은 영장류), 쿠스쿠스, 그리고 수많은 새를 찾아봅니다. 이 국립공원은 코뿔새 개체 수가 세계에서 가장 많은 곳으로, 큰코뿔새도 서식합니다. 중식 후 오후에는 탕코코 정글로 다시 한 번 탐방을 나섭니다. 숙박은 홈스테이에서 하십니다.&nbsp;</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 24 hari 3 (itinerary 6890)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('6890', 'ko', '와루가 사왕안 – 미나하사 고원 투어', '<p style="text-align:justify;">조식 후 체크아웃하고 고원 지대로 이동한 뒤, <strong>와루가 사왕안</strong>으로 향하며 미나하사인의 고대 묘역(거석 시대)에 들릅니다. 중식은 <strong>톤다노 호수</strong>에서 드십니다. 이어 토모혼으로 이동해 <strong>전통 시장</strong>을 둘러보고, <strong>월로안 마을</strong>의 조립식 목조주택 산업을 찾습니다(이곳 주민들은 해체해 마을 밖으로 실어 보낼 수 있는 정교한 미나하사식 목조주택을 짓습니다). 마지막으로 <strong>카이산티 토모혼</strong>에서 로콘산과 푸른 논을 배경으로 사진을 남깁니다.&nbsp;</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">오후는 <strong>리노우 호수</strong>에서 커피나 차를 마시며 보냅니다. 이후 토모혼의 리조트에 체크인합니다.&nbsp;</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 24 hari 4 (itinerary 6891)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('6891', 'ko', '마하우산 – 공항 이동', '<p style="text-align:justify;">호텔에서 조식 후 체크아웃합니다. 가이드와 만난 뒤 <strong>마하우산 분화구</strong>로 향합니다. 분화구 가장자리까지 10분 정도 오르면 토모혼과 마나도, 그 너머 섬들까지 이어지는 절경이 펼쳐집니다. 분화구 바닥에서는 김이 오르는 호수를 볼 수 있고 웅덩이에서 나는 유황 냄새도 느끼실 수 있습니다. 이후 가이드가 공항까지 안내해 드립니다.&nbsp;</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 25 hari 1 (itinerary 6892)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('6892', 'ko', '도착 – 미나하사 고원 – 탕코코 자연보호구역', '<p style="text-align:justify;">오전 마나도 도착. 가이드와 만난 뒤 <strong>마하우산 분화구</strong>로 향합니다. 분화구 가장자리까지 10분 정도 오르면 토모혼과 마나도, 그 너머 섬들까지 이어지는 절경이 펼쳐집니다. 이후 조립식 전통 가옥 산업의 중심지인 <strong>월로안 마을</strong>을 방문하고, 로콘산을 배경으로 사진을 남길 수 있는 <strong>불교 파고다 사원</strong>에 들릅니다. 오후에는 형형색색으로 빛나는 <strong>리노우 호수</strong>에서 호숫가의 멋진 레스토랑에 앉아 커피나 차를 마시며 여유를 즐깁니다.</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">여정은 <strong>와루가 사왕안</strong>으로 이어지며, 미나하사인의 고대 묘역(거석 시대)에 들릅니다. 이후 탕코코로 향합니다. (오후에 도착하시는 경우 미나하사 고원 일정을 생략하고 탕코코의 바투 푸티 마을로 바로 향합니다.) 숙박은 탕코코 홈스테이에서 하십니다.&nbsp;</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 25 hari 2 (itinerary 6893)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('6893', 'ko', '탕코코 종일 투어', '<p style="text-align:justify;">홈스테이에서 조식을 마친 뒤, 탕코코 자연보호구역에서 북술라웨시의 고유종 탐방을 시작합니다. 검은짧은꼬리원숭이(북술라웨시 고유의 검은 원숭이), 안경원숭이(세계에서 가장 작은 영장류), 쿠스쿠스, 그리고 수많은 새를 찾아봅니다.&nbsp;</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">이 국립공원은 코뿔새 개체 수가 세계에서 가장 많은 곳으로, 큰코뿔새도 서식합니다. 중식 후 오후에는 탕코코 정글로 다시 한 번 탐방을 나섭니다. 숙박은 홈스테이에서 하십니다.&nbsp;</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 25 hari 3 (itinerary 6894)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('6894', 'ko', '공항 이동 – 출발', '<p style="text-align:justify;">호텔에서 조식 후 체크아웃합니다. 시간이 허락하면 시내에 들러 기념품 쇼핑을 하십니다. 이후 가이드가 공항까지 안내해 드립니다. 투어가 종료됩니다. 감사합니다.&nbsp;</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 16 hari 1 (itinerary 6973)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('6973', 'ko', '일정', '<p style="text-align:justify;">전 참가자는 <strong>탈라완 마을</strong>에 위치한 <strong>투난 폭포</strong>로 이동합니다. 투난 폭포의 수원은 산에서 흘러내리는 강물로, 약 <strong>86미터 높이</strong>의 가파른 절벽을 따라 힘차게 쏟아집니다. 원시림과 자연 그대로의 주변 환경이 이 절경의 아름다움을 한층 더해 줍니다.</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">이후 현지 레스토랑에서 중식을 드십니다. 여정은 <strong>탕코코 자연보호구역</strong>으로 이어집니다. 인도네시아에서 손꼽히는 보호구역으로 향하는 길에 작은 마을들을 지나며 아름다운 풍경을 편안히 감상하시기 바랍니다.</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">보호구역은 <strong>비퉁에서 북서쪽으로 약 20킬로미터</strong> 떨어진 언덕과 계곡 사이에 자리합니다. 도착하시면 <strong>현지 공원 레인저</strong>가 맞이하여 자연 서식지에서 자유롭게 살아가는 여러 야생동물을 찾아 숲을 안내해 드립니다. 카메라를 준비해 두세요. <strong>술라웨시 검은짧은꼬리원숭이(야키)</strong>, <strong>안경원숭이(세계에서 가장 작은 영장류)</strong>, <strong>코뿔새</strong>, <strong>쿠스쿠스(눈이 큰 유대류)</strong>를 만나실 수 있습니다.&nbsp;</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">야생동물 탐방을 마친 뒤 마나도로 돌아옵니다. 투어 종료.</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 38 hari 1 (itinerary 7358)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('7358', 'ko', '일정', '<p style="text-align:justify;">조식 후 저희 팀이 마나도 시내 호텔로 모시러 갑니다. 이후 북술라웨시 특유의 해안과 시골 풍경을 감상하며 세레이 리쿠팡 부두로 이동합니다. 부두에 도착하면 전용 보트를 타고 리하가 섬으로 향합니다. 고운 백사장과 청록빛 바다, 때 묻지 않은 자연으로 유명한 열대 섬입니다.</p><p style="text-align:justify;">리하가 섬에서는 자유 시간을 즐기며 해변에서 휴식을 취하거나 맑은 바다에서 수영하실 수 있고, 섬을 거닐며 가장 아름다운 지점에서 자연을 사진에 담으실 수도 있습니다. 좀 더 활동적인 시간을 원하신다면 스노클링, 카누, 다이빙을 선택하여 잘 보존된 수중 경관을 즐기실 수 있습니다. 중식은 고요한 열대의 정취 속에서 섬에서 제공됩니다.</p><p style="text-align:justify;">오후에는 보트로 세레이 리쿠팡 부두로 돌아온 뒤 마나도 시내로 향합니다. 호텔로 돌아가기 전, 마나도 기념품 센터에 들러 현지 특산 먹거리와 수공예품, 북술라웨시의 기념품을 둘러보실 수 있습니다. 쇼핑을 마친 뒤 호텔로 모셔다 드립니다.</p><p style="text-align:justify;"><strong>투어 종료</strong></p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 18 hari 1 (itinerary 7359)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('7359', 'ko', '일정', '<p style="text-align:justify;">참가자는 오전에 픽업되어 마나도 시내에서 약 1시간 15분 거리에 있는 <strong>마하우산</strong>으로 향합니다. 마하우산은 마나도를 찾는 여행자와 등산객에게 인기 있는 명소입니다. 등산로는 약 150개의 시멘트 계단으로 이루어져 있어 비교적 수월하게 오를 수 있습니다. 오르는 길에는 손잡이용 금속 난간이 마련되어 있습니다. 정상에 오르면 마나도 투아 섬과 부나켄, 마나도 시내가 한눈에 들어오는 절경을 감상하실 수 있습니다.&nbsp;</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">이어서 토모혼의 신흥 명소인 <strong>테테타나 언덕</strong> <strong>정상</strong>으로 이동합니다. 북술라웨시 주 네 개 지역을 조망할 수 있을 뿐 아니라, 형형색색의 꽃밭에 둘러싸인 언덕의 아름다움도 함께 즐기실 수 있습니다.&nbsp;</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">이후 현지 레스토랑으로 이동해 중식을 드십니다. 식사 후 마나도 시내로 돌아와 지정된 픽업 장소에서 하차합니다. 투어 종료.</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 23 hari 1 (itinerary 7481)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('7481', 'ko', '도착 – 투난 폭포 탐방', '<p style="text-align:justify;">오전 마나도 도착. 가이드와 만난 뒤 <strong>탈라완 마을</strong>에 있는&nbsp;<strong>투난 폭포</strong>로 이동합니다.&nbsp;<strong>투난 폭포</strong>&nbsp;의 수원은 산 위의 강물로, 높이 약 86미터의 가파른 절벽을 따라 상당히 세차게 흘러내립니다. 손대지 않은 자연 그대로의 숲이 만들어 내는 분위기가&nbsp;<strong>투난 폭포</strong>&nbsp;자연 관광지의 아름다움을 한층 더해 줍니다.</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">&nbsp;이어서&nbsp;<strong>탕코코 국립공원</strong>&nbsp;으로 곧장 이동합니다 <i>(오후에 도착하시는 경우 투난 폭포 일정을 생략하고 탕코코의 바투 푸티 마을로 바로 향합니다)</i>. 늦은 오후에는 숲에서 짧은 트레킹을 하며 이 공원의 주인공, 지구상에서 가장 작은 포유류인 안경원숭이를 찾아 나섭니다. 숙박은 탕코코 생추어리 빌라에서 하십니다.</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 23 hari 2 (itinerary 7482)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('7482', 'ko', '탕코코 종일 투어', '<p style="text-align:justify;">홈스테이에서 조식을 마친 뒤, 탕코코 자연보호구역에서 북술라웨시의 고유종 탐방을 시작합니다. 검은짧은꼬리원숭이(북술라웨시 고유의 검은 원숭이), 안경원숭이(세계에서 가장 작은 영장류), 쿠스쿠스, 그리고 수많은 새를 찾아봅니다. 이 국립공원은 코뿔새 개체 수가 세계에서 가장 많은 곳으로, 큰코뿔새도 서식합니다.&nbsp;</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">중식 후 오후에는 탕코코 정글로 다시 한 번 탐방을 나섭니다. 숙박은 홈스테이에서 하십니다.&nbsp;</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 23 hari 3 (itinerary 7483)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('7483', 'ko', '와루가 사왕안 – 미나하사 고원 투어', '<p style="text-align:justify;">조식 후 체크아웃하고 고원 지대로 이동한 뒤,&nbsp;<strong>와루가 사왕안</strong>&nbsp;으로 향하며 미나하사인의 고대 묘역(거석 시대)에 들릅니다. 중식은&nbsp;<strong>톤다노 호수</strong>&nbsp;에서 드십니다. 이어 토모혼으로 이동해&nbsp;<strong>전통 시장</strong>&nbsp;을 둘러보고,&nbsp;<strong>월로안 마을</strong>&nbsp;의 조립식 목조주택 산업을 찾습니다(이곳 주민들은 해체해 마을 밖으로 실어 보낼 수 있는 정교한 미나하사식 목조주택을 짓습니다). 마지막으로&nbsp;<strong>카이산티 토모혼</strong>&nbsp;에서 로콘산과 푸른 논을 배경으로 사진을 남깁니다.&nbsp;</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">오후는&nbsp;<strong>리노우 호수</strong>&nbsp;에서 커피나 차를 마시며 보냅니다. 이후 토모혼의 리조트에 체크인합니다.&nbsp;</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 23 hari 4 (itinerary 7484)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('7484', 'ko', '마하우산 트레킹 – 부나켄 섬', '<p style="text-align:justify;">호텔에서 조식 후 체크아웃합니다. 가이드와 만난 뒤&nbsp;<strong>마하우산 분화구</strong>&nbsp;로 향합니다. 분화구 가장자리까지 10분 정도 오르면 토모혼과 마나도, 그 너머 섬들까지 이어지는 절경이 펼쳐집니다. 분화구 바닥에서는 김이 오르는 호수를 볼 수 있고 웅덩이에서 나는 유황 냄새도 느끼실 수 있습니다. 중식 후에는 보트로 부나켄 섬으로 이동합니다(보트로 약 45분).&nbsp;</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;"><strong>부나켄 해양공원</strong>&nbsp;은 인도네시아 북술라웨시, 부나켄 섬 동쪽에 자리한 해양공원입니다. 숨 막히는 수중 절경으로 널리 알려져 있습니다. 면적 약 89,065헥타르에 이르는 부나켄 해양공원은 전 세계 다이버와 스노클러가 즐겨 찾는 곳입니다. 숙박은 부나켄 섬의 리조트에서 하십니다.&nbsp;</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 23 hari 5 (itinerary 7485)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('7485', 'ko', '부나켄 섬 (수영 / 스노클링)', '<p style="text-align:justify;">인도네시아에서 가장 아름다운 스노클링 명소 중 한 곳에서 바다를 마음껏 즐깁니다. 500종이 넘는 산호와 약 1,500종의 어류가 어우러진 장엄한 생태계 한가운데에 있으며, 사람에게 해를 끼치지 않는 산호초 상어와 바다거북도 섬 주변에서 자주 목격됩니다.</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;"><strong>참고:</strong> <i>선택 사항으로 스노클링 장비를 대여해 해변에서 즐기시거나 보트 투어를 예약하실 수 있습니다. 다이빙도 가능합니다(현장 예약 및 결제).&nbsp;</i></p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 23 hari 6 (itinerary 7486)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('7486', 'ko', '공항 이동 – 출발', '<p style="text-align:justify;">호텔에서 조식 후 체크아웃합니다. 보트로 마나도까지 이동한 뒤, 가이드가 공항까지 안내해 드립니다. 투어가 종료됩니다. 감사합니다.&nbsp;</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 40 hari 1 (itinerary 7763)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('7763', 'ko', '일정', '<p style="text-align:justify;">조식 후 마나도 시내 중심가 호텔에서 모시러 가 <strong>바호워 부두</strong>로 이동합니다. 부두에서는 전용 보트를 타고 <strong>마나도 투아 섬</strong>으로 향합니다.</p><p style="text-align:justify;">도착하면 약 3시간에 걸친 마나도 투아산 트레킹으로 모험이 시작됩니다. 등산로는 열대림과 육두구, 정향, 코코넛, 바나나, 망고 등 열대 작물을 재배하는 마을 농원을 지납니다. 길을 따라 자연을 감상하실 수 있으며, 운이 좋다면 <strong>안경원숭이, 야키(검은짧은꼬리원숭이), 여러 고유종 새</strong> 등 술라웨시 고유 야생동물을 만나실 수도 있습니다.</p><p style="text-align:justify;">트레킹을 마친 뒤에는 보트로 <strong>부나켄 국립공원</strong>으로 이동합니다. 부나켄 바다의 아름다움을 둘러보는 시간을 가지며, 스노클링과 다이빙을 선택하실 수 있습니다. 중식은 도시락으로 제공되며 보트 위에서 드실 수 있습니다.</p><p style="text-align:justify;">부나켄 일정을 마친 뒤 <strong>바호워 부두</strong>로 돌아와 마나도 시내 호텔로 모셔다 드립니다.</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 41 hari 1 (itinerary 7765)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('7765', 'ko', '일정', '<p style="text-align:justify;"><strong>오전 &ndash; 픽업 &amp; 와루가 사왕안</strong><br>마나도 시내 호텔에서 모시러 간 뒤 <strong>와루가 사왕안</strong>으로 출발합니다. 수백 기의 석조 와루가가 남아 있는 미나하사의 고대 묘역으로, 미나하사 사람들의 역사와 전통, 문화유산을 가까이에서 접하실 수 있습니다.</p><p style="text-align:justify;"><strong>바투 앙우스 &amp; 스노클링</strong><br>여정은 <strong>바투 앙우스</strong>로 이어집니다. 아득한 과거의 화산 용암류가 빚어낸 인상적인 해안입니다. 현지 레스토랑에서 중식을 드신 뒤, 스노클링으로 바투 앙우스 해역을 둘러보는 시간을 가집니다. 맑은 물 덕분에 산호초와 열대어, 다양한 해양 생물을 감상하실 수 있습니다.</p><p style="text-align:justify;"><strong>오후 &ndash; 마나도로 귀환</strong><br>해변과 스노클링을 충분히 즐기신 뒤 마나도 시내로 돌아옵니다. 호텔로 모셔다 드리며 투어가 종료됩니다.</p><p style="text-align:justify;"><strong>투어 종료.</strong></p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();
COMMIT;

